#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

int main() {
    long long number;
    std::cin >> number;

    static std::vector<long long> ONES(17);
    ONES[1] = 1;
    for (int i = 2; i < 17; ++i) {
        ONES[i] = 10 * ONES[i - 1] + 1;
    }

    auto computeMinimum = [&](long long x) -> long long {
        std::function<long long(long long, int)> process = [&](long long x, int len) -> long long {
            x = std::abs(x);
            if (x % ONES[len] == 0) {
                return (x / ONES[len]) * len;
            }
            long long low = x / ONES[len];
            long long high = low + 1;

            long long option1 = low * len + process(x - low * ONES[len], len - 1);
            long long option2 = high * len + process(high * ONES[len] - x, len - 1);
            return std::min(option1, option2);
        };
        return process(x, 16);
    };

    long long result = computeMinimum(number);
    std::cout << result << std::endl;

    return 0;
}
